module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Output logic: out is 1 only when in state D
    assign out = state[3]; // D is 4'b1000, so state[3] is 1 when in state D

    // State transition logic
    // next_state is determined based on current state and input 'in'

    // For each state, determine next_state for in=0 and in=1
    // Use one-hot encoding to derive next_state

    // State A (state[0] is 1)
    // in=0: next_state = A (state[0])
    // in=1: next_state = B (state[1])
    // So next_state = (state[0] & (~in)) ? state[0] : state[1]

    // State B (state[1] is 1)
    // in=0: next_state = C (state[2])
    // in=1: next_state = B (state[1])
    // So next_state = (state[1] & (~in)) ? state[2] : state[1]

    // State C (state[2] is 1)
    // in=0: next_state = A (state[0])
    // in=1: next_state = D (state[3])
    // So next_state = (state[2] & (~in)) ? state[0] : state[3]

    // State D (state[3] is 1)
    // in=0: next_state = C (state[2])
    // in=1: next_state = B (state[1])
    // So next_state = (state[3] & (~in)) ? state[2] : state[1]

    // Combine all cases using conditional expressions
    assign next_state = 
        (state[0] & (~in)) ? state[0] : 
        (state[1] & (~in)) ? state[2] : 
        (state[2] & (~in)) ? state[0] : 
        (state[3] & (~in)) ? state[2] : 
        (state[0] & in) ? state[1] : 
        (state[1] & in) ? state[1] : 
        (state[2] & in) ? state[3] : 
        (state[3] & in) ? state[1] : 4'b0000;

endmodule

