    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current water level
            if (s[2]) begin
                // Above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
                state <= 2'd3;
            end else if (s[1]) begin
                // Between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                state <= 2'd2;
            end else if (s[0]) begin
                // Between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                state <= 2'd1;
            end else begin
                // Below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b1;
                state <= 2'd0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

