    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Internal signals for neighbor count
    reg [7:0] neighbor_count [0:255];

    // Declare offset as a module-level variable
    reg [7:0] offset;

    // Declare row as a module-level variable
    reg [7:0] row;

    // Function to compute the number of live neighbors for a cell
    function [7:0] count_neighbors;
        input [255:0] state;
        input [7:0] cell_index;
        begin
            count_neighbors = 0;
            for (int i = 0; i < 8; i++) begin
                // Compute row and column for each neighbor
                row = (cell_index / 16) + (i == 0 ? -1 : (i == 1 ? 0 : (i == 2 ? 1 : (i == 3 ? -1 : (i == 4 ? 0 : (i == 5 ? 1 : (i == 6 ? -1 : 0)))));
                int col = (cell_index % 16) + (i == 0 ? -1 : (i == 1 ? -1 : (i == 2 ? -1 : (i == 3 ? 0 : (i == 4 ? 0 : (i == 5 ? 0 : (i == 6 ? 1 : 1)))));
                // Wrap around for toroidal grid
                row = (row % 16);
                if (row < 0) row = 15;
                col = (col % 16);
                if (col < 0) col = 15;
                offset = row * 16 + col;
                if (state[offset]) count_neighbors = count_neighbors + 1;
            end
        end
    endfunction

    // Compute neighbor counts for all cells
    always @(current_q) begin
        for (int i = 0; i < 256; i++) begin
            neighbor_count[i] = count_neighbors(current_q, i);
        end
    end

    // Compute next state based on neighbor counts
    always @(neighbor_count) begin
        for (int i = 0; i < 256; i++) begin
            case (neighbor_count[i])
                0, 1: next_q[i] = 1'b0;
                2: next_q[i] = current_q[i];
                3: next_q[i] = 1'b1;
                default: next_q[i] = 1'b0;
            endcase
        end
    end

    // Load initial state on the rising edge of load
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    // Output the current state
    assign q = current_q;

endmodule

