module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    // State transitions based on sensor changes
    // State machine uses synchronous reset
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions
    always @(posedge clk) begin
        if (reset) begin
            current_state <= 3; // Equivalent to being above s[2]
            previous_state <= 3;
            fr2 <= 1;
            fr1 <= 1;
            fr0 <= 1;
            dfr <= 0;
        end else begin
            // Determine current state based on s
            if (s == 3'b000) current_state <= 3; // Above s[2]
            else if (s == 3'b001) current_state <= 2; // Between s[2] and s[1]
            else if (s == 3'b011) current_state <= 1; // Between s[1] and s[0]
            else current_state <= 0; // Below s[0]

            // Update previous_state
            previous_state <= current_state;
        end
    end

    // Determine flow rates based on current state and whether the level increased
    always @(posedge clk) begin
        if (reset) begin
            fr2 <= 1;
            fr1 <= 1;
            fr0 <= 1;
            dfr <= 0;
        end else begin
            // Determine nominal flow rate based on current state
            case (current_state)
                3: begin // Above s[2]
                    fr2 <= 0;
                    fr1 <= 0;
                    fr0 <= 0;
                    dfr <= 0;
                end
                2: begin // Between s[2] and s[1]
                    fr2 <= 0;
                    fr1 <= 0;
                    fr0 <= 1;
                    dfr <= 0;
                end
                1: begin // Between s[1] and s[0]
                    fr2 <= 0;
                    fr1 <= 1;
                    fr0 <= 1;
                    dfr <= (previous_state < current_state) ? 1 : 0;
                end
                0: begin // Below s[0]
                    fr2 <= 1;
                    fr1 <= 1;
                    fr0 <= 1;
                    dfr <= 0;
                end
            endcase
        end
    end

endmodule

